def predict_test(grid_in):
    grid = copy.deepcopy(grid_in)

    # Two frames:
    # Frame 1 at (1,1), gap at (1,3) - should be 5 but is 0
    # Frame 2 at (7,5), gap at (7,7) - should be 5 but is 0

    # Process Frame 1
    fr, fc, gap_r, gap_c = 1, 1, 1, 3

    # Fill from gap going DOWN and LEFT
    stack = [(gap_r, gap_c)]
    while stack:
        r, c = stack.pop()
        if (r, c) == (gap_r, gap_c) or grid[r][c] == 5:
            continue
        if grid[r][c] != 0:
            continue
        grid[r][c] = 2

        # Go DOWN
        dr = 0 if r in (fr + 1, fr + 2) else (1 if grid[r + 1][c] == 0 else 0)
        if dr > 0:
            if r + 1 < 10:
                if grid[r + 1][c] == 0:
                    stack.append((r + 1, c))

        # Go LEFT
        if c - 1 >= 0:
            if grid[r][c - 1] == 0 and not ((r == fr + 1 and c - 1 == fr)):
                stack.append((r, c - 1))

    # Add row above Frame 1
    for c in range(0, 5):
        if grid[0][c] == 0:
            grid[0][c] = 2

    return grid

